package com.ebdf.controller;
import com.ebdf.dao.PortalDAO;import com.google.gson.*;import javax.servlet.annotation.WebServlet;import javax.servlet.http.*;import java.io.*;import java.util.*;
@WebServlet("/api/blood-requests/invite") public class InviteDonorServlet extends HttpServlet {
 private final PortalDAO dao=new PortalDAO();private final Gson gson=new Gson();
 protected void doPost(HttpServletRequest q,HttpServletResponse p)throws IOException{p.setContentType("application/json");p.setCharacterEncoding("UTF-8");HttpSession s=q.getSession(false);if(s==null||s.getAttribute("userId")==null){p.setStatus(401);p.getWriter().write("{\"message\":\"Please login first\"}");return;}if(!"REQUESTER".equals(s.getAttribute("userRole"))){p.setStatus(403);p.getWriter().write("{\"message\":\"Requester access required\"}");return;}try{JsonObject b=gson.fromJson(q.getReader(),JsonObject.class);int requestId=b.get("requestId").getAsInt(),donorId=b.get("donorId").getAsInt();boolean ok=dao.inviteDonor(((Number)s.getAttribute("userId")).intValue(),requestId,donorId);if(!ok){p.setStatus(409);p.getWriter().write("{\"message\":\"Donor is not eligible or an invitation already exists\"}");return;}p.setStatus(201);p.getWriter().write("{\"message\":\"Donor invitation sent\"}");}catch(Exception e){getServletContext().log("donor invitation failed",e);p.setStatus(400);p.getWriter().write("{\"message\":\"Unable to send invitation\"}");}}
}
